SELECT linked_account_id, SUM(unblended_cost) FROM cur.hourly_view_all GROUP BY 1 ORDER BY 2 DESC;
SELECT DATE_TRUNC('month', usage_date) as month, SUM(unblended_cost) FROM cur.hourly_view_all GROUP BY 1;
SELECT product_code, COUNT(*) FROM cur.hourly_view_all WHERE unblended_cost > 100 GROUP BY product_code;
SELECT product_code, SUM(unblended_cost) FROM cur.hourly_view_all GROUP BY product_code;
SELECT DATE_TRUNC('day', usage_date) as usage_day, SUBSTRING(usage_type, 1, 4) as region, SUM(usage_quantity) as instance_hours FROM cur.hourly_view_all WHERE usage_type LIKE '%BoxUsage%' GROUP BY DATE_TRUNC('day', usage_date), SUBSTRING(usage_type, 1, 4) ORDER BY usage_day DESC, region;
SELECT usage_type, SUM(usage_quantity) as total_usage, SUM(unblended_cost) as total_cost FROM cur.hourly_view_all WHERE usage_type LIKE '%BoxUsage%' AND usage_date >= CURRENT_DATE - INTERVAL '30' DAY GROUP BY usage_type ORDER BY total_cost DESC;
SELECT linked_account_id, charge_type, SUM(unblended_cost) as discount_amount FROM cur.hourly_view_all WHERE charge_type LIKE '%Discount%' AND usage_date >= CURRENT_DATE - INTERVAL '30' DAY GROUP BY linked_account_id, charge_type ORDER BY discount_amount DESC;
SELECT charge_type, COUNT(*) as record_count, SUM(unblended_cost) as total_cost FROM cur.hourly_view_all WHERE usage_date >= CURRENT_DATE - INTERVAL '30' DAY GROUP BY charge_type ORDER BY total_cost DESC;
SELECT usage_date, operation, SUM(usage_quantity) as usage_amount FROM cur.hourly_view_all WHERE operation IN ('RunInstances', 'CreateVolume', 'CreateSnapshot') GROUP BY usage_date, operation ORDER BY usage_date DESC;
SELECT operation, SUM(unblended_cost) as total_cost FROM cur.hourly_view_all WHERE usage_date >= CURRENT_DATE - INTERVAL '30' DAY GROUP BY operation ORDER BY total_cost DESC LIMIT 10;
SELECT region, COUNT(DISTINCT resource_id) as resource_count, SUM(unblended_cost) as total_cost FROM cur.hourly_view_all WHERE usage_date >= CURRENT_DATE - INTERVAL '30' DAY GROUP BY region ORDER BY total_cost DESC;
SELECT resource_id, item_description, SUM(unblended_cost) as total_cost FROM cur.hourly_view_all WHERE resource_id IS NOT NULL AND usage_date >= CURRENT_DATE - INTERVAL '7' DAY GROUP BY resource_id, item_description ORDER BY total_cost DESC LIMIT 10;
SELECT pricing_unit, SUM(usage_quantity) as total_usage, SUM(unblended_cost) as total_cost FROM cur.hourly_view_all WHERE usage_date >= CURRENT_DATE - INTERVAL '30' DAY GROUP BY pricing_unit ORDER BY total_cost DESC;
SELECT region, item_description, SUM(unblended_cost) as cost FROM cur.hourly_view_all WHERE usage_date >= CURRENT_DATE - INTERVAL '30' DAY GROUP BY region, item_description ORDER BY cost DESC LIMIT 10;
SELECT pricing_term, COUNT(*) as usage_count, SUM(unblended_cost) as total_cost FROM cur.hourly_view_all WHERE usage_date >= CURRENT_DATE - INTERVAL '30' DAY GROUP BY pricing_term ORDER BY total_cost DESC;
SELECT DATE_TRUNC('day', usage_date) as usage_day, SUM(unblended_cost) as daily_cost FROM cur.hourly_view_all WHERE usage_date >= CURRENT_DATE - INTERVAL '7' DAY GROUP BY DATE_TRUNC('day', usage_date) ORDER BY usage_day DESC;
SELECT payer_account_id, linked_account_id, SUM(unblended_cost) as total_cost FROM cur.hourly_view_all WHERE usage_date >= CURRENT_DATE - INTERVAL '30' DAY GROUP BY payer_account_id, linked_account_id ORDER BY total_cost DESC;
SELECT linked_account_id, service, SUM(unblended_cost) as service_cost FROM cur.hourly_view_all GROUP BY linked_account_id, service ORDER BY service_cost DESC LIMIT 10;
SELECT savings_plan_a_r_n, SUM(unblended_cost) as total_cost, SUM(savings_plan_effective_cost) as effective_cost, SUM(unblended_cost - savings_plan_effective_cost) as savings FROM cur.hourly_view_all WHERE savings_plan_a_r_n IS NOT NULL GROUP BY savings_plan_a_r_n ORDER BY savings DESC;
SELECT reservation_a_r_n, SUM(unblended_cost) as total_cost, SUM(reservation_effective_cost) as effective_cost, SUM(unblended_cost - reservation_effective_cost) as savings FROM cur.hourly_view_all WHERE reservation_a_r_n IS NOT NULL GROUP BY reservation_a_r_n ORDER BY savings DESC;
SELECT service, SUM(unblended_cost) as on_demand_cost, SUM(reservation_effective_cost) as ri_cost, SUM(savings_plan_effective_cost) as sp_cost FROM cur.hourly_view_all WHERE usage_date >= CAST('2024-07-01' AS TIMESTAMP) AND usage_date < CAST('2024-08-01' AS TIMESTAMP) GROUP BY service ORDER BY on_demand_cost DESC;
SELECT DATE_TRUNC('day', usage_date) as usage_day, SUM(usage_quantity) as total_usage, SUM(unblended_cost) as total_cost FROM cur.hourly_view_all WHERE usage_date >= CURRENT_DATE - INTERVAL '30' DAY GROUP BY DATE_TRUNC('day', usage_date) ORDER BY usage_day;
SELECT instance_type, SUM(usage_quantity) as hours_used, SUM(unblended_cost) as on_demand_cost, SUM(reservation_effective_cost) as ri_cost FROM cur.hourly_view_all WHERE usage_type LIKE '%BoxUsage%' GROUP BY instance_type ORDER BY on_demand_cost DESC LIMIT 10;
